16	func (d *DB) CreateMemo(ctx context.Context, create *store.Memo) (*store.Memo, error) {
17		fields := []string{"uid", "creator_id", "content", "visibility", "payload"}
18		payload := "{}"
19		if create.Payload != nil {
20			payloadBytes, err := protojson.Marshal(create.Payload)
21			if err != nil {
22				return nil, err
23			}
24			payload = string(payloadBytes)
25		}
26		args := []any{create.UID, create.CreatorID, create.Content, create.Visibility, payload}
27	
28		// Add custom timestamps if provided
29		if create.CreatedTs != 0 {
30			fields = append(fields, "created_ts")
31			args = append(args, create.CreatedTs)
32		}
33		if create.UpdatedTs != 0 {
34			fields = append(fields, "updated_ts")
35			args = append(args, create.UpdatedTs)
36		}
37	
38		stmt := "INSERT INTO memo (" + strings.Join(fields, ", ") + ") VALUES (" + placeholders(len(args)) + ") RETURNING id, created_ts, updated_ts, row_status"
39		if err := d.db.QueryRowContext(ctx, stmt, args...).Scan(
40			&create.ID,
41			&create.CreatedTs,
42			&create.UpdatedTs,
43			&create.RowStatus,
44		); err != nil {
45			return nil, err
46		}
47	
48		return create, nil
49	}
