244	func (d *DB) DeleteMemo(ctx context.Context, delete *store.DeleteMemo) error {
245		where, args := []string{"id = " + placeholder(1)}, []any{delete.ID}
246		stmt := `DELETE FROM memo WHERE ` + strings.Join(where, " AND ")
247		result, err := d.db.ExecContext(ctx, stmt, args...)
248		if err != nil {
249			return errors.Wrap(err, "failed to delete memo")
250		}
251		if _, err := result.RowsAffected(); err != nil {
252			return err
253		}
254		return nil
255	}
